def transform(grid):
    """Expand the lone marker into the task's diagonal pattern."""
    n = len(grid[0])
    center = next(c for c, value in enumerate(grid[0]) if value == 2)
    out = [[0] * n for _ in range(n)]
    # The color-2 V expands one cell to each side per row until it reaches
    # both edges.
    for r in range(n):
        for c in (center - r, center + r):
            if 0 <= c < n and r <= center:
                out[r][c] = 2
    # Continue a family of parallel diagonals with spacing four. Within the
    # V they appear only strictly between its color-2 arms; below the V they
    # continue across the full width.
    for r in range(n):
        for c in range(n):
            inside_v = r <= center and center - r < c < center + r
            if (c - r - center) % 4 == 0 and out[r][c] == 0 and (inside_v or r > center):
                out[r][c] = 1
    return out
